	}
	if !strings.Contains(msg, errSimulatedWrite.Error()) {
		t.Fatalf("the shutdown write failure should still be visible in the message, got %q", msg)
	}
	if failures != 1 {
		t.Fatalf("only the one invalid complete line counts, got %d", failures)
	}
